// === pubspec.yaml (фрагмент) ===
flutter:

  # The following line ensures that the Material Icons font is
  # included with your application, so that you can use the icons in
  # the material Icons class.
  uses-material-design: true

  assets:
    - assets/images/
    - assets/icons/
    - assets/data/

  fonts:
    - family: Inter
      fonts:
        - asset: assets/fonts/Inter-Regular.ttf
        - asset: assets/fonts/Inter-SemiBold.ttf
          weight: 600

// === lib/theme/app_colors.dart (фрагмент) ===
import 'package:flutter/material.dart';

/// Власна палітра кольорів застосунку AppColors (п. 7 ТЗ ЛР 9).
/// Єдине джерело всіх кольорів застосунку, яке використовується замість
/// стандартних (Colors.blue, Colors.black тощо, п. 8 ТЗ).
///
/// Палітра поєднує неоново-темний стиль, розпочатий у Лаборатрні №8,
/// з новою світлою темою (Light / Dark mode, п. 1 ТЗ).
class AppColors {
  AppColors._();

  // ─── Основні брендові кольори ───────────────────────────────────────────
  static const Color primary = Color(0xFFD4FF00); // Неоновий лайм (акцент)
  static const Color onPrimary = Color(0xFF0D0F13); // Текст на neon-фоні
  static const Color darkBackground = Color(0xFF0D0F13);
  static const Color darkCard = Color(0xFF15181F);
  static const Color darkSurface = Color(0xFF1F2430);
  static const Color darkBorder = Color(0xFF2A3142);
  static const Color darkText = Color(0xFFFFFFFF);
  static const Color darkTextSecondary = Color(0xFF8B949E);
  static const Color darkTextHint = Color(0xFF555F70);
  static const Color darkTextDone = Color(0xFF6B7280);

  // ─── Світла тема ─────────────────────────────────────────────────────────
  static const Color lightBackground = Color(0xFFF1F3F6);
  static const Color lightCard = Color(0xFFFFFFFF);
  static const Color lightSurface = Color(0xFFE8ECF1);
  static const Color lightBorder = Color(0xFFD8DEE6);
  static const Color lightText = Color(0xFF171B21);
  static const Color lightTextSecondary = Color(0xFF5F6772);
  static const Color lightTextHint = Color(0xFF98A0AB);
  static const Color lightTextDone = Color(0xFFA6ADB8);

// === lib/theme/app_styles.dart (фрагмент) ===
import 'package:flutter/material.dart';
import 'app_colors.dart';

/// Стандартизовані стилі тексту AppStyles (п. 9 ТЗ)
/// Використовують підключений власний шрифт Inter (п. 3 ТЗ)
class AppStyles {
  // Назва підключеного шрифту
  static const String fontFamily = 'Inter';

  // 1. Заголовок (title)
  static TextStyle title({bool isDark = false, Color? color}) {
    return TextStyle(
      fontFamily: fontFamily,
      fontSize: 24,
      fontWeight: FontWeight.bold,
      letterSpacing: -0.5,
      color: color ?? (isDark ? AppColors.textDark : AppColors.textLight),
    );
  }

  // 3. Основний текст (body)
  static TextStyle body({bool isDark = false, Color? color, FontWeight? fontWeight}) {
    return TextStyle(
      fontFamily: fontFamily,
      fontSize: 14,
      fontWeight: fontWeight ?? FontWeight.normal,
      height: 1.45,
      color: color ?? (isDark ? AppColors.textDark : AppColors.textLight),
    );
  }

  // 4. Стиль для кнопок (button)
  static const TextStyle button = TextStyle(
    fontFamily: fontFamily,
    fontSize: 15,
    fontWeight: FontWeight.w600,
    letterSpacing: 0.3,
    color: Colors.white,
  );

// === lib/theme/app_theme.dart (фрагмент) ===
  /// Світла тема застосунку
  static ThemeData get lightTheme {
    return ThemeData(
      useMaterial3: true,
      brightness: Brightness.light,
      fontFamily: AppStyles.fontFamily,
      scaffoldBackgroundColor: AppColors.lightBackground,
      colorScheme: const ColorScheme.light(
        primary: AppColors.primary,
        onPrimary: AppColors.onPrimary,
        secondary: AppColors.secondary,
        surface: AppColors.lightCard,
        onSurface: AppColors.lightText,
        error: AppColors.error,
      ),
  // ... (пропуск неістотних рядків)

// === lib/main.dart ===
import 'package:flutter/material.dart';

import 'screens/welcome_screen.dart';
import 'theme/app_theme.dart';

void main() {
  runApp(const RegistrationApp());
}

/// Головний застосунок: продовження Лаборатної №8 (форми, навігація,
/// JSON-менеджер завдань) + теми оформлення та екран профілю (ЛР 9).
class RegistrationApp extends StatefulWidget {
  const RegistrationApp({super.key});

  @override
  State<RegistrationApp> createState() => _RegistrationAppState();
}

class _RegistrationAppState extends State<RegistrationApp> {
  /// Стан активної теми: true — темна, false — світла (п. 1, 2 ТЗ ЛР 9).
  /// Зберігається у класі State та оновлюється виключно через setState().
  bool _isDarkMode = true;

  void _toggleTheme(bool isDark) {
    setState(() {
      _isDarkMode = isDark;
    });
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Профіль, теми та ресурси — Лабораторна №9',
      debugShowCheckedModeBanner: false,
      // Світла та темна теми через ThemeData (п. 1, 11 ТЗ ЛР 9)
      theme: AppTheme.lightTheme,
      darkTheme: AppTheme.darkTheme,
      themeMode: _isDarkMode ? ThemeMode.dark : ThemeMode.light,
      home: WelcomeScreen(onToggleTheme: _toggleTheme),
    );
  }
}

// === lib/screens/profile_screen.dart (фрагмент) ===
import 'package:flutter/material.dart';

import '../theme/app_colors.dart';
import '../theme/app_styles.dart';

/// Екран профілю користувача ProfileScreen (п. 6 ТЗ)
class ProfileScreen extends StatelessWidget {
  /// Ім'я користувача (п. 6 ТЗ)
  final String? username;

  /// Email користувача (п. 6 ТЗ)
  final String? email;

  /// Колбек для перемикання теми (п. 2 ТЗ)
  final ValueChanged<bool>? onToggleTheme;

  const ProfileScreen({
    super.key,
    this.username,
    this.email,
    this.onToggleTheme,
  });
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;

    return Scaffold(
      backgroundColor: AppColors.background(isDark),
      appBar: AppBar(
        leading: IconButton(
          tooltip: 'Назад',
          icon: Icon(Icons.arrow_back, color: AppColors.textSecondary(isDark)),
          onPressed: () => Navigator.pop(context),
        ),
        title: Text(
          'Профіль користувача',
          style: AppStyles.title(isDark: isDark).copyWith(fontSize: 20),
        ),
        centerTitle: true,
        backgroundColor: AppColors.card(isDark),
        elevation: 0,
        actions: [
          IconButton(
            tooltip: 'Вийти з облікового запису',
            icon: Icon(Icons.logout, size: 20, color: AppColors.error),
            onPressed: () => _confirmLogout(context, isDark),
          ),
        ],
      ),
  // ... (пропуск неістотних рядків)
  /// Картка перемикання теми (п. 1, 2 ТЗ)
  Widget _buildThemeSwitchCard(BuildContext context, bool isDark) {
    return Material(
      color: AppColors.card(isDark),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(14),
        side: BorderSide(color: AppColors.divider(isDark)),
      ),
      child: SwitchListTile(
        key: const Key('theme_switch_tile'),
        secondary: Container(
          padding: const EdgeInsets.all(6),
          decoration: BoxDecoration(
            color: (isDark ? AppColors.secondary : AppColors.primary)
                .withValues(alpha: 0.15),
            shape: BoxShape.circle,
          ),
          child: Icon(
            isDark ? Icons.dark_mode : Icons.light_mode,
            size: 22,
            color: isDark ? AppColors.secondary : AppColors.text(isDark),
          ),
        ),
        title: Text(
          'Темна тема (Dark Mode)',
          style: TextStyle(
            fontFamily: AppStyles.fontFamily,
            fontWeight: FontWeight.w600,
            fontSize: 15,
            color: isDark ? AppColors.textDark : AppColors.textLight,
          ),
        ),
        subtitle: Text(
          isDark ? 'Увімкнено нічний режим' : 'Увімкнено денний режим',
          style: AppStyles.caption(isDark: isDark),
        ),
        value: isDark,
        activeThumbColor: AppColors.secondary,
        onChanged: (bool value) {
          onToggleTheme?.call(value);
        },
      ),
    );
  }
